from taf.analyzer.aasyslog_throughput.factory import (UplinkThroughputFactory, DownlinkThroughputFactory,
                                                      CAUplinkThroughputFactory, CADownlinkThroughputFactory,
                                                      create_reader)
from taf.analyzer.aasyslog_throughput.throughput_data import MbitsecThroughputResult


class AasyslogThroughput(object):

    @staticmethod
    def create_uplink_throughput(cells=None, log=None, throughput_records_output=None):
        """
        Create uplink throughput instance.

        :param cells: (optional) nrCellId list for checking throughput
        :type cells: list[str]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path
        :type throughput_records_output: str
        :return: Throughput class instance
        """
        factory = UplinkThroughputFactory()
        throughput = factory.create(cells, log, throughput_records_output)
        return throughput

    @staticmethod
    def create_downlink_throughput(cells=None, log=None, throughput_records_output=None):
        """
        Create downlink throughput instance.

        :param cells: (optional) nrCellId list for checking throughput
        :type cells: list[str]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path
        :type throughput_records_output: str
        :return: Throughput class instance
        """
        factory = DownlinkThroughputFactory()
        throughput = factory.create(cells, log, throughput_records_output)
        return throughput

    @staticmethod
    def create_ca_downlink_throughput(cells, log=None, throughput_records_output=None):
        """
        Create Carrier Aggregation downlink throughput instance.

        :param cells: nrCellId list for checking throughput
        :type cells: list[str]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path
        :type throughput_records_output: str
        :return: Throughput instance
        """
        factory = CADownlinkThroughputFactory()
        throughput = factory.create(cells, log, throughput_records_output)
        return throughput

    @staticmethod
    def create_ca_uplink_throughput(cells, log=None, throughput_records_output=None):
        """
        Create Carrier Aggregation uplink throughput instance.

        :param cells: nrCellId list for checking throughput
        :type cells: list[str]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path
        :type throughput_records_output: str
        :return: Throughput instance
        """
        factory = CAUplinkThroughputFactory()
        throughput = factory.create(cells, log, throughput_records_output)
        return throughput

    @staticmethod
    def _analyze_with_single_log(throughputs, log):
        for throughput in throughputs:
            throughput.reset()

        for throughput in throughputs:
            throughput.recorder.start()

        reader = create_reader(log)
        with reader as read:
            for log_entry in read.log_entries:
                for throughput in throughputs:
                    throughput.on_analyze(log_entry)

        for throughput in throughputs:
            throughput.recorder.stop()

    @staticmethod
    def analyze(throughputs, log=None):
        """
        Analyze and calculate throughput.

        :param throughputs: alias list for the AasyslogThroughput instance
        :type cells: list[str]
        :param log: (optional) aasyslog file path
        :type log: str
        :return: None
        """
        if not log:
            for throughput in throughputs:
                throughput.analyze()
        else:
            AasyslogThroughput._analyze_with_single_log(throughputs, log)

    @staticmethod
    def get_throughput(throughput):
        """
        Get the calculated throughput result.

        :param throughput: alias for the AasyslogThroughput instance
        :type throughput: str
        :return: List[dict] for the calculated throughput result, throughput unit is Mbit/sec
        """
        return [MbitsecThroughputResult(item) for item in throughput.get_result()]
